"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { focusRing, primaryFill } from "./_shared";

/**
 * Bold retail IconButton: a single glyph in the same materials as the
 * Button.
 *
 * It is a circle by default: the soft grey disc that holds the bag, the
 * heart and the close glyph on a store page. `primary` is the flat black
 * disc for the one action a screen offers; `inverse` is the white disc that
 * sits on product photography; ghost is the quiet choice for toolbars and
 * rows. The square shape keeps a small corner for dense grids.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    "transition-[background-color,color,border-color,scale] duration-fast ease-out",
    "active:scale-95",
    focusRing,
    "disabled:pointer-events-none disabled:border-transparent disabled:bg-secondary disabled:text-(--foreground-disabled)",
    "data-[disabled]:pointer-events-none data-[disabled]:border-transparent data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled)",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-secondary text-secondary-foreground hover:bg-(--secondary-hover)",
        primary: primaryFill,
        secondary: "bg-secondary text-secondary-foreground hover:bg-(--secondary-hover)",
        ghost: "bg-transparent text-foreground hover:bg-secondary",
        destructive: "bg-destructive text-destructive-foreground hover:bg-(--sale-deep)",
        outline:
          "border border-(--line-strong) bg-background text-foreground hover:border-foreground",
      },
      size: {
        xs: "size-7 rounded-sm [&_svg]:size-3.5",
        sm: "size-8 rounded-sm [&_svg]:size-4",
        default: "size-10 rounded-md [&_svg]:size-5",
        lg: "size-12 rounded-md [&_svg]:size-6",
        xl: "size-14 rounded-lg [&_svg]:size-6",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "circle",
    },
  },
);

/** Props for the IconButton. Give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
